fn read_length_word(bytes: &[u8], offset: &mut usize) -> Result<usize> {
    let end = checked_end(
        *offset,
        CANONICAL_LENGTH_PREFIX_BYTES,
        "canonical length word",
    )?;
    let out = read_u64_be_at(bytes, *offset, "canonical length word")?;
    *offset = end;
    usize::try_from(out).map_err(|_| anyhow!("canonical length word exceeds usize"))
}

fn checked_end(offset: usize, len: usize, context: &str) -> Result<usize> {
    offset
        .checked_add(len)
        .ok_or_else(|| anyhow!("{context} length overflows usize"))
}

fn read_exact_range<'a>(
    bytes: &'a [u8],
    offset: usize,
    len: usize,
    context: &str,
) -> Result<&'a [u8]> {
    let end = checked_end(offset, len, context)?;
    bytes
        .get(offset..end)
        .ok_or_else(|| anyhow!("{context} overruns canonical payload"))
}

fn write_exact_range(out: &mut [u8], offset: usize, bytes: &[u8], context: &str) -> Result<()> {
    let end = checked_end(offset, bytes.len(), context)?;
    let target = out
        .get_mut(offset..end)
        .ok_or_else(|| anyhow!("{context} overruns canonical output"))?;
    for (slot, byte) in target.iter_mut().zip(bytes.iter().copied()) {
        *slot = byte;
    }
    Ok(())
}

fn read_array_at<const N: usize>(bytes: &[u8], offset: usize, context: &str) -> Result<[u8; N]> {
    let source = read_exact_range(bytes, offset, N, context)?;
    let mut out = [0u8; N];
    for (slot, byte) in out.iter_mut().zip(source.iter().copied()) {
        *slot = byte;
    }
    Ok(out)
}

fn read_u64_be_at(bytes: &[u8], offset: usize, context: &str) -> Result<u64> {
    Ok(u64::from_be_bytes(read_array_at::<8>(
        bytes, offset, context,
    )?))
}

fn masked_select_u8(cond: bool, when_true: u8, when_false: u8) -> u8 {
    let mask = 0u8.wrapping_sub(u8::from(cond));
    (when_true & mask) | (when_false & !mask)
}

pub(crate) fn masked_select_bool(cond: bool, when_true: bool, when_false: bool) -> bool {
    masked_select_u8(cond, u8::from(when_true), u8::from(when_false)) != 0
}

fn masked_select_uint256(cond: bool, when_true: Uint256, when_false: Uint256) -> Uint256 {
    Uint256::from_be_bytes(masked_select_bytes(
        cond,
        when_true.to_be_bytes(),
        when_false.to_be_bytes(),
    ))
}

fn masked_eq_u8(lhs: u8, rhs: u8) -> bool {
    (lhs ^ rhs) == 0
}

fn masked_eq_uint256(lhs: Uint256, rhs: Uint256) -> bool {
    masked_eq_bytes(lhs.to_be_bytes(), rhs.to_be_bytes())
}

fn masked_select_bytes<const N: usize>(
    cond: bool,
    when_true: [u8; N],
    when_false: [u8; N],
) -> [u8; N] {
    let mask = 0u8.wrapping_sub(u8::from(cond));
    let mut selected = [0u8; N];
    for ((slot, true_byte), false_byte) in selected.iter_mut().zip(when_true).zip(when_false) {
        *slot = (true_byte & mask) | (false_byte & !mask);
    }
    selected
}

fn masked_eq_bytes<const N: usize>(lhs: [u8; N], rhs: [u8; N]) -> bool {
    let mut diff = 0u8;
    for (lhs_byte, rhs_byte) in lhs.into_iter().zip(rhs) {
        diff |= lhs_byte ^ rhs_byte;
    }
    diff == 0
}

fn masked_slice_is_zero(bytes: &[u8]) -> bool {
    let mut diff = 0u8;
    for byte in bytes {
        diff |= *byte;
    }
    diff == 0
}
